/**
 * GeneRaptor schema shape guard (19 Prisma models -> 8 on SQLite).
 *
 * Pins the trimmed data model so regressions surface in CI:
 *   - datasource is SQLite;
 *   - exactly the 8 surviving models are present;
 *   - Article keeps the engine-relevant columns and drops the stripped
 *     families (crawl FKs, wordstat, publish, autoGenerated, coverMediaId);
 *   - ResearchSource.metadata is String (SQLite has no Json type).
 */
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

const SCHEMA_PATH = resolve(process.cwd(), 'prisma/schema.prisma');
const source = readFileSync(SCHEMA_PATH, 'utf8');

function modelBlock(name) {
  const re = new RegExp(`model ${name}\\s*\\{([\\s\\S]*?)\\n\\}`, 'm');
  const m = source.match(re);
  return m ? m[1] : null;
}

function modelNames() {
  return [...source.matchAll(/^model (\w+) \{/gm)].map((m) => m[1]);
}

describe('GeneRaptor schema (§1.3): 8 models on SQLite', () => {
  it('datasource provider is sqlite', () => {
    expect(source).toMatch(/provider\s*=\s*"sqlite"/);
    expect(source).not.toMatch(/provider\s*=\s*"postgresql"/);
  });

  it('contains exactly the 8 surviving models', () => {
    expect(modelNames().sort()).toEqual([
      'AgentRoleSetting',
      'AgentRun',
      'Article',
      'ArticleVersion',
      'CompanyProfile',
      'CoverSettings',
      'ProviderConfig',
      'ResearchSource',
    ].sort());
  });

  it('Article keeps the engine-relevant columns', () => {
    const block = modelBlock('Article');
    expect(block).toBeTruthy();
    for (const field of [
      'topic',
      'targetLength',
      'userNotes',
      // D6: material language ru|en, default ru.
      'language',
      'needsReviewReason',
      'coverUrl',
      'coverModel',
      'coverPrompt',
      'coverCostRub',
      'coverGeneratedAt',
      'coverRequested',
      'coverStatus',
      'coverSkipReason',
      'status',
      'createdAt',
      'updatedAt',
    ]) {
      expect(block).toMatch(new RegExp(`\\b${field}\\b`));
    }
  });

  it('Article drops crawl FKs, wordstat, publish columns, autoGenerated, coverMediaId', () => {
    const block = modelBlock('Article');
    for (const gone of [
      'serviceId',
      'specialistId',
      'sourceSiteId',
      'wordstatKeywords',
      'wordstatStatus',
      'rentryUrl',
      'wpPostId',
      'tgMessageId',
      'manualPublishedAt',
      'autoGenerated',
      'coverMediaId',
    ]) {
      expect(block).not.toMatch(new RegExp(`\\b${gone}\\b`));
    }
  });

  it('ResearchSource.metadata is String (no Json on SQLite)', () => {
    const block = modelBlock('ResearchSource');
    expect(block).toMatch(/metadata\s+String\?/);
    expect(block).not.toMatch(/metadata\s+Json/);
  });

  it('ProviderConfig exists with kind/baseUrl/apiKey/enabled/modelsJson', () => {
    const block = modelBlock('ProviderConfig');
    expect(block).toBeTruthy();
    for (const field of ['kind', 'baseUrl', 'apiKey', 'enabled', 'modelsJson']) {
      expect(block).toMatch(new RegExp(`\\b${field}\\b`));
    }
  });
});
